"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/switch.css";
import { Switch as SwitchPrimitive } from "@base-ui/react/switch";
import { useId } from "react";
import { cn } from "../../lib/cn";

export type SwitchProps = SwitchPrimitive.Root.Props & {
  label?: string;
  description?: string;
};

export function Switch({ className, label, description, id: providedId, "aria-describedby": ariaDescribedBy, "aria-labelledby": ariaLabelledBy, ...props }: SwitchProps) {
  const generatedId = useId();
  const id = providedId ?? generatedId;
  const labelId = label ? `${id}-label` : undefined;
  const descriptionId = description ? `${id}-description` : undefined;
  const describedBy = [ariaDescribedBy, descriptionId].filter(Boolean).join(" ") || undefined;
  return (
    <div className="whatiuse-choice-row whatiuse-choice-row--spread">
      {label && (
        <label htmlFor={id} className="whatiuse-choice-copy">
          <span id={labelId}>{label}</span>
          {description && <small id={descriptionId}>{description}</small>}
        </label>
      )}
      <SwitchPrimitive.Root id={id} className={cn("whatiuse-switch", className)} aria-labelledby={ariaLabelledBy ?? labelId} aria-describedby={describedBy} {...props}>
        <SwitchPrimitive.Thumb className="whatiuse-switch__thumb" />
      </SwitchPrimitive.Root>
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-choice-row { display: flex; align-items: flex-start; gap: 9px; }

.whatiuse-choice-row--spread { align-items: center; justify-content: space-between; }

.whatiuse-choice-copy { display: grid; gap: 3px; color: var(--whatiuse-ink); font-size: 13.5px; cursor: pointer; }

.whatiuse-choice-copy small { color: var(--whatiuse-ink-tertiary); font-size: 11.5px; font-weight: 400; line-height: 1.45; }

.whatiuse-choice-row:has([data-disabled]) .whatiuse-choice-copy { opacity: 0.48; cursor: not-allowed; }

.whatiuse-switch { position: relative; display: inline-flex; width: 32px; height: 18px; flex: none; align-items: center; padding: 1px; border: 1px solid var(--whatiuse-control-border); border-radius: 999px; background: var(--whatiuse-switch-track); cursor: pointer; transition: background var(--whatiuse-fast), border-color var(--whatiuse-fast); }

.whatiuse-switch::after { position: absolute; inset: -10px; content: ""; }

.whatiuse-switch[data-checked] { border-color: var(--whatiuse-inverse); background: var(--whatiuse-inverse); }

.whatiuse-switch[data-disabled] { opacity: 0.42; cursor: not-allowed; }

.whatiuse-switch__thumb { display: block; width: 14px; height: 14px; border-radius: 50%; background: var(--whatiuse-switch-thumb); box-shadow: 0 1px 3px rgb(0 0 0 / 0.24); transform: translateX(0); transition: transform 180ms var(--whatiuse-ease-out); }

.whatiuse-switch[data-checked] .whatiuse-switch__thumb { background: var(--whatiuse-on-inverse); transform: translateX(14px); }

@media (forced-colors: active) {
.whatiuse-switch { forced-color-adjust: none; border-color: CanvasText; background: Canvas; color: CanvasText; }

.whatiuse-switch[data-checked] { background: Highlight; color: HighlightText; }
}

:root[data-theme="dark"] .whatiuse-switch[data-checked] { box-shadow: none; }

:root[data-theme="dark"] .whatiuse-switch[data-checked] .whatiuse-switch__thumb { background: var(--whatiuse-on-inverse); }

@media (prefers-reduced-motion: reduce) {
.whatiuse-switch__thumb { transition-duration: 0.01ms; }
}
}
